if (!document.body.classList.contains('ai4a11y-big-targets')) return true;
const dec = document.getElementById('btn-dec');
const inc = document.getElementById('btn-inc');
const chk = document.getElementById('expedited-shipping');
if (!dec || !inc || !chk) return false;

const decRect = dec.getBoundingClientRect();
const incRect = inc.getBoundingClientRect();
const chkRect = chk.getBoundingClientRect();

const enlarged = decRect.width >= 44 && decRect.height >= 44 &&
                 incRect.width >= 44 && incRect.height >= 44 &&
                 chkRect.width >= 24 && chkRect.height >= 24;

// No horizontal scrollbar on root
const root = document.documentElement;
const noHorizontalScroll = root.scrollWidth <= root.clientWidth + 1;

return enlarged && noHorizontalScroll;

const inc = document.getElementById('btn-inc');
const qty = document.getElementById('qty-field');
if (!inc || !qty) return false;

const startVal = parseInt(qty.value || '1', 10);
inc.click();
const clicked = parseInt(qty.value, 10) === startVal + 1;
// restore
const dec = document.getElementById('btn-dec');
if (dec) dec.click();

return clicked;
